import java.util.Scanner;

class Char {
    protected String n; protected int a;
    public Char(String n, int a) { this.n = n; this.a = a; }
    public int getA() { return a; }
    public final void disp() { System.out.println("Character: " + n); }
}

class War extends Char {
    public War(String n, int a) { super(n, a); }
    @Override public int getA() { return a * 2; }
}

class Mage extends Char {
    private int m;
    public Mage(String n, int a, int m) { super(n, a); this.m = m; }
    @Override public int getA() { return m >= 10 ? a + 50 : a; }
    public String spl() { return m >= 10 ? "Fireball cast!" : "Not enough mana to cast a spell."; }
}

public class Main {
    public static void main(String[] args) {
        Scanner s = new Scanner(System.in);
        if (!s.hasNextLine()) { err(); return; }
        String t = s.nextLine().trim();
        if (!t.equals("Warrior") && !t.equals("Mage")) { err(); return; }
        if (!s.hasNextLine()) { err(); return; }
        String n = s.nextLine().trim();
        if (n.isEmpty() || !n.matches("^[a-zA-Z\\s]+$")) { err(); return; }
        if (!s.hasNextInt()) { err(); return; }
        int a = s.nextInt();
        if (a <= 0) { err(); return; }
        Char c;
        if (t.equals("Warrior")) c = new War(n, a);
        else {
            if (!s.hasNextInt()) { err(); return; }
            int m = s.nextInt();
            if (m < 0) { err(); return; }
            c = new Mage(n, a, m);
        }
        c.disp();
        System.out.println("Attack Power: " + c.getA());
        if (c instanceof Mage) System.out.println(((Mage) c).spl());
    }
    static void err() { System.out.println("Invalid Input"); }
}

